def link(url,label,cls=''):
 return f'<a href="{esc(url,quote=True)}" class="{cls}">{label}</a>'
def button(label='Request a technical proposal',url='/request-a-proposal/',cls=''):
 return link(url,label,'button '+cls)
def header(path):
 nav=''.join(link('/'+slug+'/',title,'active' if path.startswith('/'+slug+'/') else '') for slug,title in [('solutions','Solutions'),('equipment','Equipment'),('case-studies','Case studies'),('support','Support'),('resources','Resources'),('about','About')])
 return f'<a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="/">{B}<span>UNDERWATER SYSTEMS</span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">{nav}</nav>{button("Plan your project")}</header>'
def footer():
 return f'''<footer class="footer"><div class="wrap footer-grid"><div><a class="brand" href="/">{B}<span>UNDERWATER SYSTEMS</span></a><p>Industrial underwater inspection<br>and maintenance equipment.</p><p>{COMPANY}</p></div><div><h3>Explore</h3>{link('/solutions/','Applications')}{link('/equipment/','Equipment')}{link('/case-studies/','Manufacturer cases')}</div><div><h3>Plan</h3>{link('/support/','Training & support')}{link('/resources/','Technical resources')}{link('/request-a-proposal/','Project brief')}</div><div><h3>Contact PanPan Marine</h3><p>Equipment selection, project enquiries<br>and manufacturer coordination.</p><a class="contact-email" href="mailto:{EMAIL}">{EMAIL}</a>{link('/about/','About PanPan Marine')}</div></div><div class="wrap footer-bottom"><span>© {B} 2026</span><span>Manufacturer: Boya Gongdao / ROBOOCEAN</span><span>{link('/privacy/','Privacy')} · {link('/terms/','Terms')}</span></div></footer>'''
def cta(title='Bring your project into focus.',text='Share the task, site conditions and required results. Build a clear brief for system selection.'):
 return f'<section class="cta"><div class="wrap cta-grid"><div><p class="eyebrow">FROM TASK TO CONFIGURATION</p><h2>{title}</h2><p>{text}</p></div>{button("Plan your project",cls="lime")}</div></section>'
def faq(rows):
 return '<div class="faq">'+''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in rows)+'</div>'
def img(p,cls='',lazy=True):
 return f'<img class="{cls}" src="/assets/{p["img"]}" alt="Boya Gongdao {p["name"]} {p["kind"]}" width="900" height="650" '+('loading="lazy"' if lazy else 'fetchpriority="high"')+'>'
def product_card(p):
 return f'<article class="product-card"><a class="product-image" href="/equipment/{p["slug"]}/">{img(p)}</a><div class="product-copy"><span class="eyebrow">{p["kind"]}</span><h3>{link("/equipment/"+p["slug"]+"/",p["name"])}</h3><p>{p["summary"]}</p>{link("/equipment/"+p["slug"]+"/","View equipment","text-link")}</div></article>'
def solutions_cards():
 return '<div class="solution-grid">'+''.join(f'<a class="solution-card" href="/solutions/{s["slug"]}/"><span class="number">{s["no"]} / {s["verb"]}</span><h3>{s["title"]}</h3><p>{s["lead"]}</p><span class="text-link">Explore application</span></a>' for s in SOLUTIONS)+'</div>'
def intro(label,title,lead):
 return f'<section class="page-intro"><div class="wrap"><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lead">{lead}</p></div></section>'
def section_list(title,items):
 return f'<h3>{title}</h3><ul class="clean-list">'+''.join('<li>'+esc(i)+'</li>' for i in items)+'</ul>'
def write(path,title,description,body,noindex=False):
 PAGES.append(dict(path=path,title=title,description=description))
 dest=DIST/path.strip('/')/'index.html' if path!='/' else DIST/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True)
 canonical=f'<link rel="canonical" href="{ORIGIN}{path}">' if ORIGIN else ''
 schema={'@context':'https://schema.org','@type':'WebPage','name':title,'description':description}
 if ORIGIN: schema['url']=ORIGIN+path
 schema['publisher']={'@type':'Organization','name':C['legal_company'],'url':ORIGIN,'email':C['contact_email']}
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | {B}</title><meta name="description" content="{esc(description,quote=True)}">{canonical}<meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><meta property="og:title" content="{esc(title,quote=True)} | {B}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:site_name" content="{B}"><meta property="og:image" content="{ORIGIN}/assets/ad-400.jpg"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{json.dumps(schema)}</script><script defer src="/assets/site.js"></script></head><body>{header(path)}<main id="main">{body}</main>{footer()}</body></html>'''
 dest.write_text(html,encoding='utf-8')

