write('/solutions/','Underwater Robotics Applications','Explore industrial inspection, long-distance tunnel inspection, underwater trash-rack cleaning and sump dredging.',intro('APPLICATIONS','Start with the task.','Four applications. Different conditions. A complete system selected around the work.')+'<section class="wrap section">'+solutions_cards()+'</section>'+cta())

